CREATE TABLE `partner_combo` (
	`id` INT(11) NOT NULL,
	`kod` VARCHAR(15) NULL COLLATE 'utf8mb4_general_ci',
	`nev` VARCHAR(150) NULL COLLATE 'utf8mb4_general_ci',
	`kuj` VARCHAR(30) NOT NULL COLLATE 'utf8mb4_general_ci',
	`ktj` VARCHAR(30) NOT NULL COLLATE 'utf8mb4_general_ci',
	`irsz` VARCHAR(10) NULL COLLATE 'utf8mb4_general_ci',
	`telepules` VARCHAR(30) NULL COLLATE 'utf8mb4_general_ci',
	`kerulet` VARCHAR(5) NULL COLLATE 'utf8mb4_general_ci',
	`kozterulet` VARCHAR(150) NULL COLLATE 'utf8mb4_general_ci',
	`kozt_jelleg` VARCHAR(10) NULL COLLATE 'utf8mb4_general_ci',
	`hazszam` VARCHAR(5) NULL COLLATE 'utf8mb4_general_ci',
	`epulet` VARCHAR(5) NULL COLLATE 'utf8mb4_general_ci',
	`lepcsohaz` VARCHAR(5) NULL COLLATE 'utf8mb4_general_ci',
	`emelet` VARCHAR(5) NULL COLLATE 'utf8mb4_general_ci',
	`ajto` VARCHAR(5) NULL COLLATE 'utf8mb4_general_ci',
	`hrsz` VARCHAR(5) NULL COLLATE 'utf8mb4_general_ci',
	`email` VARCHAR(50) NULL COLLATE 'utf8mb4_general_ci',
	`telefon` VARCHAR(20) NULL COLLATE 'utf8mb4_general_ci',
	`combo` VARCHAR(166) NULL COLLATE 'utf8mb4_general_ci',
	`cim` VARCHAR(245) NULL COLLATE 'utf8mb4_general_ci',
	`magansz` TINYINT(1) NOT NULL,
	`adoszam` VARCHAR(13) NOT NULL COLLATE 'utf8mb4_general_ci',
	`ado_azon` VARCHAR(8) NOT NULL COLLATE 'utf8mb4_general_ci',
	`ado_kod` VARCHAR(1) NOT NULL COLLATE 'utf8mb4_general_ci',
	`ado_megye_kod` VARCHAR(2) NOT NULL COLLATE 'utf8mb4_general_ci',
	`d_id` INT(11) NOT NULL
) ENGINE=MyISAM;

-- Struktúra mentése függvény muraszemenye_porta. partner_keszlete
DROP FUNCTION IF EXISTS `partner_keszlete`;
DELIMITER //
CREATE FUNCTION `partner_keszlete`(`p_id_p` INT,
	`t_id_p` INT,
	`tar_id_p` INT,
	`tort_p` TINYINT
) RETURNS double
    DETERMINISTIC
BEGIN
DECLARE amenny DECIMAL(12,2);
SELECT IFNULL(SUM(MENNY),0)  FROM keszlet WHERE partner_id=p_id_p AND t_id=t_id_p AND tarolo_id=tar_id_p AND tort=tort_p INTO amenny;
RETURN amenny;
END//
DELIMITER ;

