-- Struktúra mentése trigger muraszemenye_porta. merlegjegy_before_insert
DROP TRIGGER IF EXISTS `merlegjegy_before_insert`;
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER `merlegjegy_before_insert` BEFORE INSERT ON `merlegjegy` FOR EACH ROW BEGIN 
SET NEW.ev_ssz:=(SELECT IF((SELECT  MAX(EV_SSZ) from merlegjegy  WHERE YEAR(tavdatum)=YEAR(CURRENT_TIMESTAMP) and tul_id=NEW.tul_id) is NULL,1,(SELECT  MAX(EV_SSZ) from merlegjegy WHERE YEAR(tavdatum)=YEAR(CURRENT_TIMESTAMP) and tul_id=NEW.tul_id)+1)) ;
SET NEW.sorszam:=CONCAT(NEW.tul_elotag, CAST(YEAR(NEW.tavdatum) AS CHAR),'/', LPAD(CAST(NEW.ev_ssz AS CHAR),6,'0'));
 END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Struktúra mentése trigger muraszemenye_porta. rak_szall_before_insert
DROP TRIGGER IF EXISTS `rak_szall_before_insert`;
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER `rak_szall_before_insert` BEFORE INSERT ON `rak_szall` FOR EACH ROW BEGIN
SET NEW.ev_ssz:=(SELECT IF((SELECT  MAX(EV_SSZ) from rak_szall  WHERE YEAR(datum)=YEAR(CURRENT_TIMESTAMP)) is NULL,1,(SELECT  MAX(EV_SSZ) from rak_szall WHERE YEAR(datum)=YEAR(CURRENT_TIMESTAMP))+1)) ;
SET NEW.sorszam:=CONCAT(CAST(YEAR(NEW.datum) AS CHAR),'/', LPAD(CAST(NEW.ev_ssz AS CHAR),6,'0'));
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Struktúra mentése nézet muraszemenye_porta. felrakodasi_cimek_nezet
DROP VIEW IF EXISTS `felrakodasi_cimek_nezet`;
-- Ideiglenes tábla eltávolítása és a végső VIEW struktúra létrehozása
DROP TABLE IF EXISTS `felrakodasi_cimek_nezet`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `felrakodasi_cimek_nezet` AS SELECT id,tul_id,
irsz,telepules,kozterulet,kozt_jelleg,hazszam,epulet,lepcsohaz,emelet,ajto,hrsz,
email,telefon,
CONCAT(irsz,' ',telepules,' ', if(kozterulet<>'',CONCAT(kozterulet),' '),
if(kozt_jelleg<>'',CONCAT(' ',kozt_jelleg),''),if(hazszam<>'',CONCAT(' ',hazszam),''),if(epulet<>'',CONCAT(' ',epulet),''),
if(lepcsohaz<>'',CONCAT(' ',lepcsohaz),''),if(emelet<>'',CONCAT(' ',emelet ),''),
if(ajto<>'',CONCAT(' ',ajto),''),if(hrsz<>'',CONCAT(' ',hrsz),'')) AS cim
from felrakodasi_cimek ;

-- Struktúra mentése nézet muraszemenye_porta. keszlet_nezet
DROP VIEW IF EXISTS `keszlet_nezet`;
-- Ideiglenes tábla eltávolítása és a végső VIEW struktúra létrehozása
DROP TABLE IF EXISTS `keszlet_nezet`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `keszlet_nezet` AS SELECT k.t_id AS Term_id, term.kod AS Term_kod,term.nev AS Term_nev,
k.Tarolo_id, tar.nev AS Tarolo_nev,k.partner_id,p.kod AS Partner_kod,p.nev AS Partner_nev,
k.f_id AS felhasznalo_id,f.nev AS Felhasznalo_nev,k.menny,k.modositva,k.tort
FROM keszlet k
INNER JOIN termek term ON term.ID=k.t_id
INNER JOIN tarolok tar ON tar.id=k.tarolo_id
INNER JOIN partner p ON p.ID=k.partner_id
LEFT JOIN felhasz f ON f.id=k.f_id ;

-- Struktúra mentése nézet muraszemenye_porta. lerakodasi_cimek_nezet
DROP VIEW IF EXISTS `lerakodasi_cimek_nezet`;
-- Ideiglenes tábla eltávolítása és a végső VIEW struktúra létrehozása
DROP TABLE IF EXISTS `lerakodasi_cimek_nezet`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `lerakodasi_cimek_nezet` AS SELECT id,tul_id,
irsz,telepules,kozterulet,kozt_jelleg,hazszam,epulet,lepcsohaz,emelet,ajto,hrsz,
email,telefon,
CONCAT(irsz,' ',telepules,' ', if(kozterulet<>'',CONCAT(kozterulet),' '),
if(kozt_jelleg<>'',CONCAT(' ',kozt_jelleg),''),if(hazszam<>'',CONCAT(' ',hazszam),''),if(epulet<>'',CONCAT(' ',epulet),''),
if(lepcsohaz<>'',CONCAT(' ',lepcsohaz),''),if(emelet<>'',CONCAT(' ',emelet ),''),
if(ajto<>'',CONCAT(' ',ajto),''),if(hrsz<>'',CONCAT(' ',hrsz),'')) AS cim
from lerakodasi_cimek ;

-- Struktúra mentése nézet muraszemenye_porta. partner_combo
DROP VIEW IF EXISTS `partner_combo`;
-- Ideiglenes tábla eltávolítása és a végső VIEW struktúra létrehozása
DROP TABLE IF EXISTS `partner_combo`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `partner_combo` AS SELECT id,kod,nev,kuj,ktj,
irsz,telepules,kerulet,kozterulet,kozt_jelleg,hazszam,epulet,lepcsohaz,emelet,ajto,hrsz,
email,telefon, CONCAT(kod,' ',nev) As combo,
CONCAT(irsz,' ',telepules,' ', if(kerulet<>'',CONCAT(kerulet,' '),''),if(kozterulet<>'',CONCAT(kozterulet),' '),
if(kozt_jelleg<>'',CONCAT(' ',kozt_jelleg),''),if(hazszam<>'',CONCAT(' ',hazszam),''),if(epulet<>'',CONCAT(' ',epulet),''),
if(lepcsohaz<>'',CONCAT(' ',lepcsohaz),''),if(emelet<>'',CONCAT(' ',emelet ),''),
if(ajto<>'',CONCAT(' ',ajto),''),if(hrsz<>'',CONCAT(' ',hrsz),'')) AS cim, magansz,
if(ado_azon<>0,CONCAT(CAST(ado_azon AS CHAR),'-',CAST(ado_kod AS CHAR),'-',CAST(ado_megye_kod AS CHAR)),'') AS adoszam, ado_azon, ado_kod,ado_megye_kod, 
d_id from partner ;

-- Struktúra mentése nézet muraszemenye_porta. rak_szall_lista_nezet
DROP VIEW IF EXISTS `rak_szall_lista_nezet`;
-- Ideiglenes tábla eltávolítása és a végső VIEW struktúra létrehozása
DROP TABLE IF EXISTS `rak_szall_lista_nezet`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `rak_szall_lista_nezet` AS SELECT r.*,rt.id AS rt_id,rt.termek_id,rt.termek_kod,rt.termek_nev,rt.mennyiseg,rt.tort
FROM rak_szall r
INNER JOIN rak_szall_tet rt ON rt.RK_ID=r.ID ;

